// Security headers for app.junctionverse.com. Single source for:
//   - `npm run preview` (vite.config.ts), so the policy can be tested locally
//   - deploy/nginx/security-headers.conf (generated by `npm run headers:nginx`)
//
// connect-src lists everything the browser calls: the Junction API and Firebase
// (Auth for the custom-token sign-in, Firestore for chats). img-src allows S3, where
// listing photos, selfies and chat images live. Geolocation stays allowed for this
// site because the pickup-area picker and address pin use it.

export const API_ORIGIN = 'https://api.junctionverse.com'

const csp = [
  ["default-src", ["'self'"]],
  ["script-src", ["'self'"]],
  ["connect-src", [
    "'self'",
    API_ORIGIN,
    'https://firestore.googleapis.com',
    'https://identitytoolkit.googleapis.com',
    'https://securetoken.googleapis.com',
  ]],
  ["img-src", ["'self'", 'data:', 'blob:', 'https://*.amazonaws.com']],
  ["style-src", ["'self'", "'unsafe-inline'"]],
  ["font-src", ["'self'"]],
  ["object-src", ["'none'"]],
  ["frame-ancestors", ["'none'"]],
  ["base-uri", ["'none'"]],
  ["form-action", ["'self'"]],
]
  .map(([name, values]) => `${name} ${values.join(' ')}`)
  .join('; ')

export function securityHeaders({ hsts = true } = {}) {
  return {
    'Content-Security-Policy': csp,
    ...(hsts ? { 'Strict-Transport-Security': 'max-age=31536000; includeSubDomains' } : {}),
    'X-Content-Type-Options': 'nosniff',
    'Referrer-Policy': 'strict-origin-when-cross-origin',
    'X-Frame-Options': 'DENY',
    'Permissions-Policy': 'camera=(), microphone=(), geolocation=(self)',
  }
}
